async function baselineHttp(t,f){
 const express=require('express'),app=express();app.use(express.json({limit:'12mb'}));app.use((req,_res,next)=>{req.user={id:7};next();});app.use('/api/v04',loadSource(path.join(root,'src/v04/router.ts'),f.db,f.cache,f.oss).default);const server=await new Promise(resolve=>{const s=app.listen(0,'127.0.0.1',()=>resolve(s));});t.after(()=>server.close());
 const post=async(route,body,status=200)=>{const r=await fetch('http://127.0.0.1:'+server.address().port+'/api/v04'+route,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const result=await r.json();assert.equal(r.status,status,JSON.stringify(result));return status===200?result.data:result;};
 const context={...f.scope,currentStage:'studio',currentRoute:'studio',selectedObject:{type:'ASSET',key:'CHAR-001'}};
 const upload=async(png=f.png)=>post('/agent/image/upload',{context,name:'baseline.png',dataUrl:'data:image/png;base64,'+png.toString('base64')});
 const preview=async(a,role='GENERAL')=>{const turn=await post('/agent/studio-turn',{context,message:role==='FACE_HERO'?'把这张设为脸部参考':role==='FULL_BODY_BACK'?'把这张设为背面参考':'以后以这张作为这个男孩的基准图。',attachmentIds:[a.id]});assert.equal(turn.mode,'ASSET_IMAGE_BASELINE');return turn.baselinePreview;};
 const confirm=p=>post('/studio/image-baseline/confirm',{...f.scope,canonicalKey:p.canonicalKey,attachmentId:p.attachmentId,role:p.role,previewHash:p.previewHash});
 return {post,context,upload,preview,confirm};
}
