 assert.equal((await f.db('o_v04StudioAssetDraftJob').where({canonicalKey:'BRAND-001'})).length,0);assert.equal((await f.db('o_v04StudioAssetDraftJob').where({canonicalKey:'CHAR-001'})).length,1);
 assert.deepEqual(await f.db('o_v04Asset'),before);assert.equal((await f.db('o_v04AssetVisualSpec')).length,0);
